import { MeshBasicNodeMaterial, PlaneGeometry, Group, Texture } from 'three/webgpu';
import { texture, uv, mix, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Planar background with brushed metal and gradient ---
  const geometry = new PlaneGeometry(1.6, 1.0);
  const material = new MeshBasicNodeMaterial();

  // Gradient from surface (#0b0b10) to paper (#e8ecf2) vertical
  const surfaceColor = vec3(0.043, 0.043, 0.063);   // #0b0b10
  const paperColor = vec3(0.91, 0.925, 0.95);       // #e8ecf2
  const gradient = mix(surfaceColor, paperColor, uv().y);

  // Texture node (placeholder, replaced when image loads)
  const dummyTexture = new Texture();
  const texNode = texture(dummyTexture);
  const blended = mix(texNode, gradient, 0.5);  // grain + gradient
  material.colorNode = blended;

  const mesh = new ctx.THREE.Mesh(geometry, material);
  group.add(mesh);

  // Load the brushed metal texture asynchronously
  let loadedTex = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTex = tex;
    tex.wrapS = tex.wrapT = ctx.THREE.ClampToEdgeWrapping;
    texNode.value = tex;
    material.needsUpdate = true;
  });

  // --- Text label from config.textContent ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMesh = (() => {
    if (textItems.length === 0) return null;
    const item = textItems[0];
    const fontSize = item.typography?.fontSize ?? 39;
    const color = item.typography?.color ?? '#16161d';
    const text = item.text;

    const opts = {
      fontSize,
      color,
      align: 'center',
    };
    const meshObj = ctx.fontAtlas.createText(text, opts);
    meshObj.position.z = 0.01;  // slightly in front of plane
    return meshObj;
  })();
  if (textMesh) group.add(textMesh);

  // --- Cleanup and event handlers (none) ---
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTex) loadedTex.dispose();
    if (textMesh) {
      // Assume createText returns a Mesh
      textMesh.traverse((child) => {
        if (child.isMesh) {
          child.geometry?.dispose();
          child.material?.dispose();
        }
      });
    }
    // No GSAP timelines to kill
  };

  return group;
}
